/bin/bash -lc "python - <<'PY'
import json
for fn in ['book-model.json','native-national-scope.json','prerequisite-context.json']:
 d=json.load(open(fn)); print('\\nFILE',fn)
 def shape(x,depth=0):
  if depth>3: return
  if isinstance(x,dict):
   for k,v in x.items():
    print(' '*depth,k,':',type(v).__name__,(len(v) if hasattr(v,'__len__') else ''))
    if isinstance(v,(dict,list)): shape(v,depth+1)
  elif isinstance(x,list):
   if x: shape(x[0],depth+1)
 shape(d)
PY"

