/bin/bash -lc "python - <<'PY'
import json
for fn in ['batch.input.jsonl','description-review-input.json']:
 d=json.loads(open(fn).read())
 print('\\nFILE',fn)
 def summarise(x,path=''):
  if isinstance(x,dict):
   for k,v in x.items():
    p=path+'/'+k
    if k in ['reviewContext','evidenceProfile']: print(p,'omitted for separate complete inspection')
    elif isinstance(v,(dict,list)):
     print(p,type(v).__name__,len(v)); summarise(v,p)
    else: print(p,repr(v))
  elif isinstance(x,list):
   for i,v in enumerate(x): summarise(v,path+'/'+str(i))
 summarise(d)
PY"

